const $=id=>document.getElementById(id);let number='2',weapon='Pistola',version=0,catalog=[],vehicle=null,onlyFav=false,favs=new Set();let storageOK=true;try{const saved=JSON.parse(localStorage.getItem('entorno-favs')||'[]');if(Array.isArray(saved))favs=new Set(saved.filter(x=>typeof x==='string'));}catch{storageOK=false}
const colors=['negro','blanco','gris','gris oscuro','plateado','rojo','rojo oscuro','azul','azul marino','azul claro','verde','verde oscuro','verde lima','amarillo','naranja','morado','rosa','marrón','beige','dorado','bronce','turquesa','granate','camuflaje','varios colores','no se distingue'];
const situations=[['amenazando a alguien','está amenazando a alguien','están amenazando a alguien'],['atracando una tienda','está atracando una tienda','están atracando una tienda'],['robando un vehículo','está robando un vehículo','están robando un vehículo'],['forzando una puerta','está forzando una puerta','están forzando una puerta'],['disparando','está disparando','están disparando'],['peleándose','está golpeando a otra persona','están peleándose'],['reteniendo a alguien','está reteniendo a alguien','están reteniendo a alguien'],['persiguiendo a alguien','está persiguiendo a alguien','están persiguiendo a alguien'],['huyendo del lugar','está huyendo del lugar','están huyendo del lugar'],['conduciendo temerariamente','está conduciendo de forma temeraria','están conduciendo de forma temeraria'],['destrozando mobiliario','está destrozando mobiliario','están destrozando mobiliario'],['rondando la zona','está dando vueltas por la zona','están dando vueltas por la zona'],['discutiendo a gritos','está discutiendo a gritos con alguien','están discutiendo a gritos'],['sacando objetos de un local','está sacando objetos de un local','están sacando objetos de un local'],['golpeando un coche','está golpeando un coche','están golpeando un coche'],['entrando en una propiedad','está entrando en una propiedad','están entrando en una propiedad'],['tirando objetos','está tirando objetos a la calle','están tirando objetos a la calle'],['pidiendo ayuda','está pidiendo ayuda','están pidiendo ayuda']];
function options(id,items){$(id).replaceChildren(...items.map((s,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=s;return o}));}
options('situation',situations.map(x=>x[0]));const places=['en una tienda','en una gasolinera','en un banco','en una joyería','en la calle','en un callejón','en un aparcamiento','en un taller','en un bar','en un restaurante','en una vivienda','en una nave industrial','en el puerto','en el aeropuerto','en la playa','en la autopista','cerca del hospital','cerca de comisaría','en un motel','en un supermercado','en una armería','en un concesionario','en una plaza','en un garaje','en una zona rural','en un camping','en una obra','en una estación de tren','en un club nocturno','en un almacén'];options('place',places);
const clothes=['ropa de calle','sudadera y pantalón largo','chándal','traje','chaqueta y vaqueros','camiseta y vaqueros','camiseta y pantalón corto','ropa deportiva','ropa de motorista','mono de trabajo','ropa táctica','ropa de camuflaje','abrigo largo','chaleco y pantalón largo','camisa y pantalón','ropa de playa','uniforme de seguridad','ropa de repartidor','ropa de mecánico','ropa elegante','ropa ancha','ropa diferente entre sí','no se distingue'];options('clothing',clothes);options('clothcolor',colors);options('carcolor',colors);$('carcolor').value='2';const faces=['sin detalle visible','con pasamontañas','con la cara cubierta por una máscara','con un pañuelo tapando la cara','con casco integral','con gorra','con capucha puesta','con gafas de sol','con sombrero','con casco de moto abierto','con máscara de payaso','con máscara de animal','con gorro de lana','con mochila','con bolsa de deporte'];options('face',faces);options('finish',['sin especificar','mate','metalizado','cromado','perlado']);
const detailTexts=['Se oyen gritos.','Se oyen disparos.','Hay una persona en el suelo.','Se ve sangre en el suelo.','Hay cristales rotos.','El vehículo tiene los cristales tintados.','El vehículo tiene golpes visibles.','El motor sigue encendido.','Las puertas del vehículo están abiertas.','Se ha oído una alarma.','Hay humo en la zona.','Hay fuego visible.','Una persona lleva una bolsa.','Se ven guantes.','La matrícula no se distingue.','Hay gente corriendo.','Se han subido al vehículo.','El vehículo se ha marchado.'];detailTexts.forEach((text,i)=>{const l=document.createElement('label');l.className='check';const c=document.createElement('input');c.type='checkbox';c.value=text;c.id='detail'+i;l.append(c,document.createTextNode(text));$('details').append(l)});
function chips(id,items,current,callback){$(id).replaceChildren(...items.map(value=>{const b=document.createElement('button');b.type='button';b.textContent=value;b.setAttribute('aria-pressed',String(value===current));b.onclick=()=>{callback(value);chips(id,items,value,callback);generate()};return b}));}chips('numbers',['1','2','3','4','5','6','Más de 6'],number,x=>number=x);chips('weapons',['Desarmado','Pistola','Escopeta','Navaja','Pincho','No se distingue'],weapon,x=>weapon=x);
const categories={COMPACT:'Compactos',SEDAN:'Sedanes',SUV:'SUV',COUPE:'Cupés',MUSCLE:'Muscle',SPORT_CLASSIC:'Clásicos deportivos',SPORT:'Deportivos',SUPER:'Superdeportivos',MOTORCYCLE:'Motos',OFF_ROAD:'Todoterreno',INDUSTRIAL:'Industriales',UTILITY:'Utilitarios',VAN:'Furgonetas',CYCLE:'Bicicletas',BOAT:'Barcos',HELICOPTER:'Helicópteros',PLANE:'Aviones',SERVICE:'Servicios',EMERGENCY:'Emergencias',MILITARY:'Militares',COMMERCIAL:'Comerciales',RAIL:'Trenes',OPEN_WHEEL:'Monoplazas'};
const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function filtered(){const q=norm($('search').value);return catalog.filter(c=>(!onlyFav||favs.has(c.id))&&(!$('category').value||c.category===$('category').value)&&norm(c.name+' '+c.brand+' '+c.id).includes(q))}
function renderCars(){const rows=filtered();$('cars').replaceChildren();rows.forEach(c=>{const row=document.createElement('div');row.className='vehicle'+(vehicle?.id===c.id?' selected':'');const b=document.createElement('button');b.type='button';b.className='choose';b.setAttribute('aria-pressed',String(vehicle?.id===c.id));b.append(document.createTextNode(c.name));const small=document.createElement('small');small.textContent=[c.brand,c.id,categories[c.category]||c.category].filter(Boolean).join(' · ');b.append(small);b.onclick=()=>{vehicle=c;renderCars();generate()};const star=document.createElement('button');star.type='button';star.className='star';star.textContent=favs.has(c.id)?'★':'☆';star.setAttribute('aria-label',(favs.has(c.id)?'Quitar de':'Añadir a')+' favoritos: '+c.name);star.setAttribute('aria-pressed',String(favs.has(c.id)));star.onclick=()=>{favs.has(c.id)?favs.delete(c.id):favs.add(c.id);try{localStorage.setItem('entorno-favs',JSON.stringify([...favs]));storageOK=true}catch{storageOK=false}renderCars()};row.append(b,star);$('cars').append(row)});if(!rows.length)$('cars').textContent=onlyFav?'No hay favoritos con estos filtros. Marca ☆ junto a un vehículo.':'No se han encontrado vehículos. Prueba otro nombre.';$('selected').textContent='Seleccionado: '+(vehicle?vehicle.name:'ninguno');$('catalogstatus').textContent=rows.length+' de '+catalog.length+' modelos · '+favs.size+' favoritos'+(!storageOK?' · No se pueden guardar los favoritos en este navegador.':'');}
$('search').oninput=renderCars;$('category').onchange=renderCars;$('favfilter').onclick=()=>{onlyFav=!onlyFav;$('favfilter').setAttribute('aria-pressed',String(onlyFav));$('favfilter').textContent=onlyFav?'★ Solo favoritos':'☆ Favoritos';renderCars()};
const selectedText=id=>$(id).selectedOptions[0].textContent;const pick=a=>a[version%a.length];function generate(){if($('length').value==='brief'){generateBrief();return}const one=number==='1';const qty=one?'una persona':number==='Más de 6'?'más de seis personas':number+' personas';const situation=situations[+$('situation').value][one?1:2];const tone=$('tone').value;const starts={n:['¿Hola, policía? Escuchen, por favor:','¡Policía! Necesito contarles lo que estoy viendo:','¿Es la policía? Atiéndanme, por favor:'],s:['Buenas, policía. Quiero informar de lo siguiente:','Hola, policía. Les cuento lo que estoy viendo:','Policía, llamo para avisar de esta situación:'],c:['¿Policía? Oigan, que aquí está pasando algo:','¡Eh, policía! Miren lo que está pasando:','¿Hola, policía? Escuchen un momento:']};const endings={n:['¡VENGAN A ECHAR UN VISTAZO, POR FAVOR!','¡MANDEN UNA PATRULLA, POR FAVOR!','¡POR FAVOR, VENGAN A COMPROBAR QUÉ OCURRE!'],s:['¿Pueden enviar una patrulla a comprobar qué ocurre?','Por favor, envíen a alguien a echar un vistazo.','Les agradecería que vinieran a comprobarlo.'],c:['¡Manden a alguien, que esto no me da buena espina!','¡Vengan a echar un vistazo, por favor!','¡Pasen por aquí a comprobar qué está ocurriendo!']};let p=[pick(starts[tone]),'Veo a '+qty+' '+places[+$('place').value]+'; '+situation+'.'];const cloth=selectedText('clothing'),color=selectedText('clothcolor'),face=selectedText('face');if(cloth!=='no se distingue')p.push((one?'Lleva ':'Llevan ')+cloth+(color==='no se distingue'?'':color==='varios colores'?' de varios colores':' de color '+color)+'.');if(face!=='sin detalle visible')p.push((one?'Va ':'Van ')+face+'.');const weapons={Desarmado:one?'No le veo armas.':'No les veo armas.',Pistola:(one?'Lleva':'Una de esas personas lleva')+' una pistola en la mano.',Escopeta:(one?'Lleva':'Una de esas personas lleva')+' una escopeta en las manos.',Navaja:(one?'Lleva':'Una de esas personas lleva')+' una navaja en la mano.',Pincho:(one?'Lleva':'Una de esas personas lleva')+' un pincho en la mano.','No se distingue':'No alcanzo a distinguir si '+(one?'lleva':'llevan')+' armas.'};p.push(weapons[weapon]);if($('travel').value==='foot')p.push(one?'Va a pie.':'Van a pie.');else if($('travel').value==='unknown')p.push('No he visto ningún vehículo.');else if(vehicle){let col=selectedText('carcolor'),finish=selectedText('finish');p.push('El vehículo que veo es un '+vehicle.name+(col==='no se distingue'?'':col==='varios colores'?' de varios colores':' de color '+col)+(finish==='sin especificar'?'':', con acabado '+finish)+'.');}document.querySelectorAll('#details input:checked').forEach(c=>p.push(c.value));const extra=$('extra').value.trim();if(extra)p.push(extra.replace(/[.!?]+$/,'')+'.');if($('length').value==='normal')p.push(pick(tone==='n'?['Estoy muy nervioso, no sé qué hacer.','Me está temblando la voz, perdonen.','No me gusta nada lo que estoy viendo.']:tone==='c'?['Joder, esto no me gusta un pelo.','Qué cojones, no me esperaba ver algo así.','No sé cómo va a acabar esto.']:['Les cuento lo que alcanzo a ver desde aquí.','Eso es lo que he podido observar.','No tengo más detalles por el momento.']));p.push(pick(endings[tone]));$('output').textContent='/entorno '+p.join(' ');count();$('status').textContent='';}
function count(){$('count').textContent=$('output').textContent.length+' caracteres'}$('form').onsubmit=e=>{e.preventDefault();version++;generate()};$('variant').onclick=()=>{version++;generate()};$('form').addEventListener('change',()=>{const active=$('travel').value==='vehicle';$('garage').hidden=!active;generate()});$('extra').oninput=generate;$('tone').onchange=generate;$('length').onchange=generate;$('output').oninput=count;$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('output').textContent);$('status').textContent='Copiado. Listo para pegar en el servidor.'}catch{const range=document.createRange();range.selectNodeContents($('output'));const sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);$('status').textContent='Texto seleccionado. Pulsa Ctrl+C para copiar.'}};$('reset').onclick=()=>{$('form').reset();number='2';weapon='Pistola';chips('numbers',['1','2','3','4','5','6','Más de 6'],number,x=>number=x);chips('weapons',['Desarmado','Pistola','Escopeta','Navaja','Pincho','No se distingue'],weapon,x=>weapon=x);$('carcolor').value='2';vehicle=catalog.find(c=>c.id==='massacro')||catalog[0];onlyFav=false;$('favfilter').setAttribute('aria-pressed','false');$('favfilter').textContent='☆ Favoritos';$('garage').hidden=false;renderCars();generate()};
fetch('vehicles.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{catalog=data.sort((a,b)=>a.name.localeCompare(b.name));for(const c of [...new Set(catalog.map(v=>v.category))].sort()){const o=document.createElement('option');o.value=c;o.textContent=categories[c]||c;$('category').append(o)}vehicle=catalog.find(c=>c.id==='massacro')||catalog[0];renderCars();generate()}).catch(()=>{$('catalogstatus').textContent='No se ha podido cargar el catálogo. Recarga la página para reintentar.'});generate();

function renderTravelButtons(){const items=[['vehicle','Seleccionar coche'],['foot','A pie'],['unknown','No se ha visto vehículo']];$('travel-buttons').replaceChildren(...items.map(([value,label])=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.setAttribute('aria-pressed',String($('travel').value===value));b.onclick=()=>{$('travel').value=value;$('garage').hidden=value!=='vehicle';renderTravelButtons();generate()};return b}));}
const resetWithTravel=$('reset').onclick;$('reset').onclick=()=>{resetWithTravel();renderTravelButtons()};renderTravelButtons();

function generateBrief(){const one=number==='1',qty=one?'Una persona':number==='Más de 6'?'Más de 6 personas':number+' personas';let text=qty+' '+situations[+$('situation').value][0]+' '+places[+$('place').value];const clothing=selectedText('clothing'),color=selectedText('clothcolor');if(clothing!=='no se distingue')text+=color==='no se distingue'?', con '+clothing:color==='varios colores'?', ropa multicolor':', ropa de color '+color;const arms={Pistola:'pistola',Escopeta:'escopeta',Navaja:'navaja',Pincho:'pincho'};if(arms[weapon])text+=', '+arms[weapon]+' visible';else if(weapon==='Desarmado')text+=', sin armas visibles';text+='.';if($('travel').value==='foot')text+=' '+(one?'Va':'Van')+' a pie.';else if($('travel').value==='vehicle'&&vehicle){const col=selectedText('carcolor');text+=' Vehículo: '+vehicle.name+(col==='no se distingue'?'':' ('+col+')')+'.'}$('output').textContent='/entorno '+text;count();$('status').textContent='';}
